-- Server-side PREPARE example. Supply real 384-dimensional MiniLM embeddings
-- generated by scripts/embed.ts or src/lib/embedding.ts; no synthetic fallback.
PREPARE exercise_matches(vector,text,text) AS
SELECT id,name,description,category,1-(embedding <=> $1) AS similarity
FROM exercises WHERE embedding IS NOT NULL AND embedding_model=$2
AND ($3 IS NULL OR category=$3)
ORDER BY embedding <=> $1 LIMIT 5;
-- EXECUTE exercise_matches('[actual 384 values]', 'Xenova/all-MiniLM-L6-v2', NULL);
-- The application executes the equivalent bound query; exact search for this small catalog.
DEALLOCATE exercise_matches;
